import {courses,institutions,categories,provinces,levels,dimensions,getInstitution,assessment,findCourses,sampleVideo} from './model.js';
import {institutionCredential,chamberLogo} from './credentials.js';
import {findRelatedCourses} from './related-courses.js?v=7';

const main=document.querySelector('#main');
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=value=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(value);
const number=value=>new Intl.NumberFormat('es-AR').format(value);
const paths={
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
 book:'<path d="M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v14c-4-1-6 0-9 2-3-2-5-3-9-2Z"/>',
 screen:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',
 level:'<path d="M4 20v-5h4v5m2 0V9h4v11m2 0V3h4v17"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 filter:'<path d="M3 6h18M6 12h12M9 18h6"/>',
 certificate:'<rect x="4" y="3" width="16" height="15" rx="2"/><path d="M8 7h8M8 11h4"/><circle cx="16" cy="16" r="3"/><path d="m14 19-1 4 3-1 3 1-1-4"/>',
 play:'<path d="m9 5 11 7-11 7Z" fill="currentColor" stroke="none"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 message:'<path d="M21 11a9 9 0 0 1-9 9 9 9 0 0 1-4-1l-5 2 1-5a9 9 0 1 1 17-5Z"/>',
 tool:'<path d="m14 6 4 4M4 20l7-7m1-10a7 7 0 0 0 9 9l-4-4 1-4-4 1Z"/>',
 bag:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18m-11 0v3h4v-3"/>',
 globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
 instagram:'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r=".8" fill="currentColor"/>',
 facebook:'<path d="M15 22V13h3l1-4h-4V7c0-2 1-2 4-2V2h-4c-4 0-5 3-5 6v1H7v4h3v9"/>',
 linkedin:'<path d="M4 10v10M4 5v.1M10 20V10m0 4c0-5 9-5 9 0v6"/>',
 youtube:'<rect x="2" y="5" width="20" height="14" rx="4"/><path d="m10 9 5 3-5 3Z"/>'
};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;
const categoryIcon={'Tecnología':'screen','Administración':'bag','Comunicación':'message','Oficios':'tool','Idiomas':'globe','Gastronomía':'book'};
const logo=(i,large=false)=>`<span class="institution-logo ${large?'large':''}" role="img" aria-label="Logo de ejemplo de ${escape(i.name)}" style="--logo-x:${i.logo.column*50}%;--logo-y:${i.logo.row*100}%"></span>`;
const badge=i=>institutionCredential(i);
const stars=c=>c.rating?`<span class="stars" aria-hidden="true">★</span><strong>${c.rating.toLocaleString('es-AR',{minimumFractionDigits:1})}</strong><span class="review-count">(${c.reviews} opiniones de ejemplo)</span>`:'<span class="review-count">Todavía sin opiniones</span>';
const socialNames={instagram:'Instagram',facebook:'Facebook',linkedin:'LinkedIn',youtube:'YouTube'};
const socialHosts={instagram:['instagram.com','www.instagram.com'],facebook:['facebook.com','www.facebook.com'],linkedin:['linkedin.com','www.linkedin.com'],youtube:['youtube.com','www.youtube.com']};
function socialURL(value,network){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&socialHosts[network].includes(u.hostname)?u.href:null}catch{return null}}
function socials(i){return `<div class="social-links" aria-label="Redes de ${escape(i.name)}">${Object.entries(socialNames).map(([key,name])=>{const url=socialURL(i.socials[key],key);return url?`<a class="social-button" href="${escape(url)}" target="_blank" rel="noopener noreferrer" aria-label="${name} de ${escape(i.name)}">${icon(key,18)}<span>${name}</span></a>`:`<button class="social-button" data-social="${key}" data-institute="${i.id}" aria-label="${name} de ${escape(i.name)}: acceso de ejemplo">${icon(key,18)}<span>${name}</span></button>`}).join('')}</div>`}
const certificate=()=>`<span class="certificate-tag">${icon('certificate',17)}Certificado de la Cámara</span>`;
const params=()=>Object.fromEntries(new URLSearchParams(location.hash.split('?')[1]||''));
let filtersOpen=false;
function searchTo(updates={},reset=false){const p=new URLSearchParams(reset?{}:params());Object.entries(updates).forEach(([k,v])=>v?p.set(k,v):p.delete(k));const hash=`#/buscar${p.size?'?'+p:''}`;if(location.hash===hash)renderMarketplace('buscar');else location.hash=hash;if(reset)window.scrollTo(0,0);}
const option=(value,label,selected)=>`<option value="${escape(value)}" ${value===(selected||'')?'selected':''}>${escape(label)}</option>`;
const breadcrumb=(label,parent='Cursos',path='buscar')=>`<div class="breadcrumb"><a href="#/${path}">${parent}</a><span>/</span><span>${escape(label)}</span></div>`;
const setMain=html=>{main.innerHTML=html};

function courseCard(c){const i=getInstitution(c.institution);return `<article class="product-card">
 <a class="product-cover category-${categories.indexOf(c.category)}" href="#/curso/${c.id}" tabindex="-1" aria-hidden="true"><span class="category-photo" style="--photo-x:${(categories.indexOf(c.category)%3)*50}%;--photo-y:${categories.indexOf(c.category)<3?'16':'84'}%"></span><span class="cover-category">${icon(categoryIcon[c.category],15)}${c.category}</span>${c.video?`<span class="cover-video">${icon('play',15)}Video de muestra</span>`:''}</a>
 <div class="product-body"><div class="product-institution"><a class="institution-identity" href="#/instituto/${i.id}">${logo(i)}<span>${i.name}</span></a></div>
 <h3><a href="#/curso/${c.id}">${c.title}</a></h3><p class="product-outcome"><strong>VAS A PODER</strong>${c.outcomes[0]}</p><div class="product-rating">${stars(c)}</div>${certificate()}
 <div class="product-meta"><span>${icon('screen',15)}${c.mode}</span><span>${icon('clock',15)}${c.hours} horas</span><span>${c.difficulty}</span></div>
 ${badge(i)}<div class="product-bottom"><div class="product-price"><small>Valor total · ejemplo</small><strong>${money(c.price)}<small> ARS</small></strong></div><a href="#/curso/${c.id}" class="button">Ver curso</a></div></div>
 </article>`}

function filterPanel(f){return `<aside id="market-filters" class="market-filters ${filtersOpen?'open':''}" aria-label="Filtros"><div class="filter-head"><h2>Refiná tu búsqueda</h2><button class="text-button" data-clear>Limpiar</button></div>
 <div class="filter-block"><h3>Área de formación</h3><div class="filter-options">${['',...categories].map(cat=>`<label class="check-label"><input type="radio" name="category" value="${cat}" ${cat===(f.category||'')?'checked':''}>${cat||'Todas las áreas'}<span class="count">${cat?courses.filter(c=>c.category===cat).length:courses.length}</span></label>`).join('')}</div></div>
 <div class="filter-block"><h3>Modalidad</h3><div class="filter-options">${['','Online','Presencial','Híbrida'].map(mode=>`<label class="check-label"><input type="radio" name="mode" value="${mode}" ${mode===(f.mode||'')?'checked':''}>${mode||'Todas'}</label>`).join('')}</div></div>
 <div class="filter-block"><label for="province-filter">Provincia del instituto</label><select id="province-filter" name="province">${option('','Todas las provincias',f.province)}${provinces.map(p=>option(p,p,f.province)).join('')}</select></div>
 <div class="filter-block"><label for="level-filter">Nivel institucional</label><select id="level-filter" name="level">${option('','Todos los niveles',f.level)}${levels.map(l=>option(l.key,l.name,f.level)).join('')}${option('sin-evaluar','En evaluación',f.level)}</select></div>
 <div class="filter-block"><label for="duration-filter">Carga horaria</label><select id="duration-filter" name="duration">${option('','Cualquier duración',f.duration)}${option('short','Hasta 40 horas',f.duration)}${option('long','Más de 40 horas',f.duration)}</select></div>
 <div class="filter-help">${icon('level',26)}<strong>Elegí con más información.</strong><p>Conocé qué hay detrás del nivel de cada instituto.</p><a href="#/niveles">Cómo evaluamos</a></div></aside>`}

function renderSearch(){const f=params(),results=findCourses(f),filtered=Object.entries(f).some(([key,value])=>key!=='sort'&&value);
 setMain(`<div class="market-container"><div class="category-rail" aria-label="Explorar áreas"><a class="${!f.category?'selected':''}" href="#/buscar">${icon('grid')}Todas las áreas</a>${categories.map(cat=>`<a class="${f.category===cat?'selected':''}" href="#/buscar?category=${encodeURIComponent(cat)}">${icon(categoryIcon[cat])}${cat}</a>`).join('')}</div>
 ${!filtered?`<section class="discovery-banner"><div class="banner-copy"><span class="eyebrow">TU PRÓXIMO PASO EMPIEZA ACÁ</span><h1>Aprendé algo nuevo.<br><em>Abrí nuevas posibilidades.</em></h1><p>Explorá cursos, conocé a los institutos<br class="desktop-only"> y elegí con el respaldo de la Cámara.</p><button class="banner-video" data-video="sample">${icon('play',18)}Así se ve una clase de ejemplo</button></div><div class="banner-photo"><img src="./assets/digital-learning.png" alt="Imagen ilustrativa de una persona aprendiendo online" width="1536" height="1024"><div class="banner-stamp">${icon('certificate',27)}<span>Cursos con<br><strong>certificado de la Cámara</strong></span></div></div></section><div class="trust-rail"><div>${icon('book',24)}<span><strong>Encontrá tu formación</strong>Cursos online, presenciales e híbridos</span></div><div>${icon('certificate',24)}<span><strong>Certifica la Cámara</strong>El instituto dicta el curso</span></div><div>${icon('level',24)}<span><strong>Conocé a cada instituto</strong>Su nivel, su propuesta y sus redes</span></div></div>`:''}
 <div class="market-workspace"><div><button class="mobile-filter-toggle" data-toggle-filters aria-controls="market-filters" aria-expanded="${filtersOpen}">${icon('filter',18)}Filtros</button>${filterPanel(f)}</div>
 <section class="market-results" aria-label="Resultados"><div class="results-head"><div><span class="eyebrow">${filtered?'RESULTADOS DE TU BÚSQUEDA':'ENCONTRÁ LO QUE TE MUEVE'}</span><h${filtered?'1':'2'}>${f.q?'Cursos para “'+escape(f.q)+'”':f.category?escape(f.category):'Explorá nuestros cursos'}</h${filtered?'1':'2'}><p>${results.length} ${results.length===1?'curso':'cursos'} de ejemplo · ${institutions.length} instituciones ficticias</p></div><label class="sort-label"><span>Ordenar por</span><select id="market-sort">${option('relevance','Relevancia',f.sort||'relevance')}${option('rating','Opiniones del curso',f.sort)}${option('level','Nivel del instituto',f.sort)}${option('price','Menor precio',f.sort)}</select></label></div>
 <div class="active-filters">${Object.entries(f).filter(([k,v])=>v&&k!=='sort').map(([k,v])=>`<button class="chip" data-remove="${escape(k)}" aria-label="Quitar filtro ${escape(v)}">${escape(levels.find(l=>l.key===v)?.name||({'sin-evaluar':'En evaluación',short:'Hasta 40 horas',long:'Más de 40 horas'}[v])||v)} ×</button>`).join('')}</div>
 ${f.q&&(!f.sort||f.sort==='relevance')?'<p class="relevance-note">Ordenados por coincidencia con tu búsqueda. El sello informa el nivel del instituto y no modifica este orden.</p>':''}<div class="product-grid" aria-live="polite">${results.length?results.map(courseCard).join(''):`<div class="empty">${icon('search',36)}<h2>No encontramos cursos con esos filtros</h2><p>Probá otra palabra o ampliá la modalidad, provincia o nivel.</p><button class="button" data-clear>Ver todos los cursos</button></div>`}</div><p class="source-note">Catálogo ilustrativo. Instituciones, imágenes, opiniones y niveles de demostración. Logo de la Cámara tomado de su sitio oficial.</p></section></div></div>`);
}

function mediaGallery(c){return `<div class="course-gallery"><div class="gallery-main"><img id="gallery-image" src="${c.cover}" alt="${c.coverAlt}" width="1536" height="1024">${c.video?`<button class="gallery-play" data-video="${c.id}" aria-label="Reproducir clase de ejemplo de Excel">${icon('play',34)}<span>Ver clase de ejemplo</span></button>`:''}<span class="media-caption">Imagen ilustrativa · no corresponde a una sede real</span></div><div class="gallery-thumbs"><button class="gallery-thumb selected" data-photo="${c.cover}" data-alt="${c.coverAlt}" aria-pressed="true"><img src="${c.cover}" alt="Portada" width="120" height="80"></button><button class="gallery-thumb" data-photo="./assets/technical-workshop.png" data-alt="Ejemplo ilustrativo de formación práctica" aria-pressed="false"><img src="./assets/technical-workshop.png" alt="Ejemplo de taller" width="120" height="80"></button>${c.video?`<button class="gallery-thumb video-thumb" data-video="${c.id}">${icon('play',24)}<span>Video</span></button>`:''}<span>Conocé la propuesta<br>antes de elegir.</span></div></div>`}

function relatedSection(c){const related=findRelatedCourses(c);return `<section id="relacionados" class="section related-courses" aria-labelledby="related-title"><div class="section-title"><div><h2 id="related-title">Cursos relacionados</h2><p>Otras propuestas que también te pueden interesar.</p></div>${related.length?`<a class="text-link" href="#/buscar?${new URLSearchParams({category:c.category})}">Ver más de ${escape(c.category)}</a>`:''}</div>${related.length?`${related.length>1?'<p class="related-hint">Deslizá para descubrir más cursos.</p>':''}<div class="product-grid related-grid" role="region" aria-label="Cursos relacionados" tabindex="0">${related.map(courseCard).join('')}</div>`:'<div class="related-empty"><p>Todavía no hay otras propuestas relacionadas en el catálogo.</p><a class="button secondary" href="#/buscar">Explorar todos los cursos</a></div>'}</section>`}

function renderCourse(id){const c=courses.find(c=>c.id===id);if(!c)return notFound();const i=getInstitution(c.institution);
 setMain(`<div class="market-container detail-container">${breadcrumb(c.title)}
 <div class="course-heading"><span class="eyebrow">${c.category} · ${c.difficulty}</span><h1>${c.title}</h1><p class="course-result-lead">${c.outcomes[0]}</p><div class="course-head-meta"><div class="product-rating">${stars(c)}</div><span>${icon('screen',16)}${c.mode}</span><span>${icon('clock',16)}${c.hours} horas · ${c.weeks} semanas</span>${certificate()}</div><div class="learning-skills" aria-label="Habilidades que vas a desarrollar">${c.skills.map(skill=>`<span>${skill}</span>`).join('')}</div></div>
 <div class="course-detail-grid"><div class="course-content">
 <nav class="detail-tabs" aria-label="En esta ficha"><button data-section="objetivos">Objetivos</button><button data-section="dirigido-a">Dirigido a</button><button data-section="resultados">Qué vas a lograr</button><button data-section="programa">Programa</button><button data-section="certificacion">Certificación</button><button data-section="instituto">Instituto</button></nav>
 <section id="objetivos" class="section course-objectives"><h2>Objetivos</h2><p>${escape(c.objectives)}</p></section>
 <section id="dirigido-a" class="section course-audience"><h2>Dirigido a</h2><ul class="course-audience-list">${c.audience.map(person=>`<li>${escape(person)}</li>`).join('')}</ul><div class="audience-box"><h3>Qué necesitás para empezar</h3><p>${c.prerequisites}</p></div></section>
 <section id="resultados" class="section outcomes-section"><h2>Al terminar, vas a poder…</h2><ul class="outcome-list">${c.outcomes.map(outcome=>`<li><span class="outcome-check">${icon('check',16)}</span><span>${outcome}</span></li>`).join('')}</ul>
 <div class="project-example">${icon('bag',30)}<div><span class="eyebrow">APRENDER HACIENDO</span><h3>Tu trabajo práctico</h3><p>${c.project}</p><div class="course-evaluation"><strong>Cómo se evalúa</strong><p>${c.evaluation}</p></div></div></div><p class="source-note">Resultados y actividades de ejemplo para esta propuesta de curso.</p>
 </section>
 <section class="section"><h2>Conocé la experiencia de aprendizaje</h2>${mediaGallery(c)}</section>
 <section id="programa" class="section"><h2>Un programa para llegar a ese resultado</h2><p class="detail-lead">${c.description}</p><ol class="syllabus">${c.modules.map(m=>`<li>${m}</li>`).join('')}</ol></section>
 <section id="certificacion" class="section certification-block"><div><div class="certification-brand"><div class="certificate-symbol">${icon('certificate',34)}</div>${chamberLogo()}</div><span class="eyebrow">CERTIFICACIÓN DEL CURSO</span><h2>Tu aprendizaje, certificado por la Cámara.</h2><p>El instituto dicta la formación. Al cumplir los requisitos de aprobación, recibís el certificado emitido por la Cámara.</p><div class="course-evaluation"><strong>Evaluación prevista en esta ficha</strong><p>${c.evaluation}</p></div><p class="small">El instituto confirma las condiciones de aprobación. El sello institucional y las opiniones del curso se muestran por separado.</p><span class="small">Educación no formal. La certificación no equivale por sí sola a un título oficial ni a una habilitación profesional. Ficha de ejemplo.</span></div></section>
 <section id="instituto" class="section"><div class="section-title"><h2>Conocé quién te forma</h2><a class="text-link" href="#/instituto/${i.id}">Ver perfil completo</a></div><div class="seller-detail"><div class="seller-heading">${logo(i,true)}<div><h3>${i.name}</h3><p>${icon('pin',15)}${i.city}, ${i.province}</p></div></div>${badge(i)}<p>${i.description}</p>${socials(i)}<span class="small">Redes ilustrativas, pendientes de enlaces reales.</span></div></section>
 <section class="section"><h2>Opiniones de estudiantes</h2><div class="review-panel"><div class="product-rating">${stars(c)}</div><p>${c.reviews?'Valoraciones de ejemplo. En el catálogo real se mostrarán opiniones vinculadas a cursadas verificadas.':'Todavía no hay opiniones. Esto no implica una evaluación negativa del curso.'}</p></div></section></div>
 <aside class="purchase-panel"><div class="seller-mini"><a href="#/instituto/${i.id}">${logo(i)}<span>Dictado por<strong>${i.name}</strong></span></a>${badge(i)}</div><span class="small">Valor total de ejemplo</span><div class="purchase-price">${money(c.price)}<small> ARS</small></div><p class="payment-note">Consultá formas de pago con el instituto.</p><div class="purchase-features"><span>${icon('certificate')}Certificado emitido por la Cámara</span><span>${icon('screen')}${c.mode==='Online'?'Aprendé desde donde estés':c.mode+' · '+i.city}</span><span>${icon('clock')}${c.weeks} semanas de duración orientativa</span><span>${icon('book')}${c.difficulty==='Inicial'?'Formación de nivel inicial':'Requiere conocimientos básicos del área'}</span></div><button class="button" data-contact="${c.id}">Consultar por este curso</button><p class="small purchase-disclaimer">El instituto confirma inicio, cupos y condiciones. Este prototipo no recibe inscripciones ni pagos.</p>${socials(i)}</aside></div>${relatedSection(c)}</div>`);
}

function institutionCard(i){return `<article class="school-card"><div class="school-brand">${logo(i,true)}<div><h3><a href="#/instituto/${i.id}">${i.name}</a></h3><span class="small">${i.specialty}</span></div></div>${badge(i)}<p>${i.description}</p><div class="school-facts"><span>${icon('pin',15)}${i.city}</span><span>${i.courses} cursos de ejemplo</span></div>${socials(i)}<a class="button secondary" href="#/instituto/${i.id}">Conocer instituto</a></article>`}
function renderInstitutions(){setMain(`<div class="market-container detail-container"><div class="page-heading"><span class="eyebrow">UNA RED DE POSIBILIDADES</span><h1>Encontrá tu lugar para aprender.</h1><p>Institutos con identidad propia, cursos para distintos objetivos y una comunidad que podés conocer.</p></div><div class="school-grid">${institutions.map(institutionCard).join('')}</div><p class="source-note">Instituciones y logos ficticios para visualizar la propuesta. Los enlaces a redes se completarán con las cuentas reales de los socios.</p></div>`)}

function renderInstitute(id){const i=getInstitution(id);if(!i)return notFound();const a=assessment(i),offering=courses.filter(c=>c.institution===id);
 setMain(`<div class="market-container detail-container">${breadcrumb(i.name,'Instituciones','instituciones')}<section class="school-hero"><div class="school-hero-content">${logo(i,true)}<div><span class="eyebrow">INSTITUCIÓN DE LA RED · EJEMPLO</span><h1>${i.name}</h1><p>${i.specialty}</p><div class="school-hero-meta"><span class="institution-level-label">${a.name}</span><span>${icon('pin',16)}${i.city}, ${i.province}</span></div></div></div><div class="school-hero-photo"><img src="${id==='oficios'?'./assets/technical-workshop.png':'./assets/digital-learning.png'}" alt="Imagen ilustrativa de formación" width="1536" height="1024"></div></section>
 <div class="school-social-bar"><span>Conectá con el instituto</span>${socials(i)}<small>Accesos de ejemplo</small></div><div class="school-intro"><p>${i.description}</p><span>${icon('certificate',23)}Cursos con certificado de la Cámara</span></div>
 <section class="institution-credential-overview">${institutionCredential(i,false)}<div class="institution-credential-context"><span class="eyebrow">CONOCÉ EL RESPALDO</span><h2>Una credencial con criterios a la vista.</h2><p>${a.score===null?'La institución está reuniendo la evidencia necesaria para obtener su nivel. Podés consultar su oferta y conocer la propuesta de cada curso.':'El sello reúne la experiencia de estudiantes, la propuesta formativa y la evidencia institucional. Cada curso conserva su propia valoración.'}</p><ul><li>${icon('book',19)}Nivel del instituto, independiente de la dificultad del curso.</li><li>${icon('certificate',19)}Certificado del curso emitido por la Cámara.</li><li>${icon('clock',19)}${a.score===null?'Evaluación pendiente: todavía sin nivel.':'Revisión de ejemplo: octubre de 2026.'}</li></ul></div></section>
 <div class="stat-row"><div class="stat"><strong>${i.courses}</strong><span>Cursos declarados de ejemplo</span></div><div class="stat"><strong>${number(i.certificates)}</strong><span>Certificados · últimos 24 meses</span></div><div class="stat"><strong>${i.rating.toLocaleString('es-AR',{minimumFractionDigits:1})}/5</strong><span>${i.reviews} opiniones de ejemplo</span></div><div class="stat"><strong>${a.ordinal?a.ordinal+' de 4':'Pendiente'}</strong><span>${a.name} · ejemplo</span></div></div>
 <section class="section"><div class="section-title"><h2>Explorá sus cursos</h2><span class="small">${offering.length} fichas de ejemplo</span></div><div class="product-grid institution-products">${offering.map(courseCard).join('')}</div></section>
 <section class="section two-col"><div><h2>Su nivel, explicado.</h2><div class="institution-score-note"><span>${a.score===null?'Sin puntaje hasta completar la evidencia.':'Puntaje ilustrativo detrás de la credencial'}</span><strong>${a.score??'—'}<small>${a.score===null?'':' / 100'}</small></strong></div><div class="breakdown">${dimensions.map(d=>`<div class="dimension"><div class="dimension-label"><strong>${d.name}</strong><span>${i.scores[d.key]===null?'Pendiente':i.scores[d.key]+'/100'} · peso ${d.weight}%</span></div><div class="bar" role="meter" aria-label="${d.name}" aria-valuemin="0" aria-valuemax="100" ${i.scores[d.key]===null?'aria-valuetext="Pendiente"':`aria-valuenow="${i.scores[d.key]}"`}><span style="width:${i.scores[d.key]??0}%"></span></div></div>`).join('')}</div></div><div class="content-panel"><h2>Más información para elegir</h2><p>${a.score===null?'Este instituto todavía está incorporando evidencia. La falta de datos no significa una valoración negativa.':a.description}</p><ul><li>El nivel evalúa al instituto; cada curso tiene sus propias opiniones.</li><li>La Cámara emite el certificado de la formación, según los requisitos aplicables.</li><li>Las redes ayudan a conocer su comunidad y actividad.</li><li>El volumen de certificados aporta trayectoria, no garantiza calidad.</li></ul><p class="notice">${a.score===null?'Este ejemplo tiene cuatro opiniones, por debajo del mínimo propuesto de diez.':'Evaluación ilustrativa: octubre de 2026. No es una clasificación de un socio real.'}</p><a class="text-link" href="#/niveles">Ver criterios de evaluación</a></div></section></div>`);
}

function notFound(){setMain('<div class="page"><div class="empty"><h1>No encontramos esta página</h1><p>Podés continuar explorando el catálogo.</p><a class="button" href="#/buscar">Buscar cursos</a></div></div>')}
function openVideo(courseId){const video=courseId==='sample'?sampleVideo:courses.find(c=>c.id===courseId)?.video;if(!video)return;const dialog=document.querySelector('#media-dialog');document.querySelector('#media-title').textContent='Así se vería una clase en la ficha';document.querySelector('#media-content').innerHTML=`<div class="video-stage"><iframe title="${escape(video.title)} — ${escape(video.author)}" src="https://www.youtube-nocookie.com/embed/${video.id}?rel=0" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><p><strong>Material de muestra, en inglés.</strong> “${escape(video.title)}”, de ${escape(video.author)}. Es contenido de un tercero, no una clase del instituto ficticio ni de la Cámara.</p><a class="text-link" href="${video.url}" target="_blank" rel="noopener noreferrer">Abrir el video original en YouTube</a><div class="notice">Cada socio podrá presentar su propio video, una clase de muestra o imágenes de sus instalaciones. El enlace público y la autorización de uso se incorporarán a su ficha.</div>`;dialog.showModal()}
document.querySelector('#media-dialog').addEventListener('close',()=>document.querySelector('#media-content').replaceChildren());
document.querySelector('#global-search').addEventListener('submit',event=>{event.preventDefault();searchTo({q:new FormData(event.currentTarget).get('q').trim()})});
main.addEventListener('change',event=>{if(event.target.closest('#market-filters')&&event.target.name)searchTo({[event.target.name]:event.target.value});if(event.target.id==='market-sort')searchTo({sort:event.target.value})});
main.addEventListener('click',event=>{
 const target=event.target.closest('button');if(!target)return;
 if(target.hasAttribute('data-clear')){filtersOpen=false;searchTo({},true)}
 if(target.hasAttribute('data-remove'))searchTo({[target.dataset.remove]:''});
 if(target.hasAttribute('data-toggle-filters')){filtersOpen=!filtersOpen;document.querySelector('#market-filters').classList.toggle('open',filtersOpen);target.setAttribute('aria-expanded',String(filtersOpen))}
 if(target.dataset.video)openVideo(target.dataset.video);
 if(target.dataset.photo){const img=document.querySelector('#gallery-image');img.src=target.dataset.photo;img.alt=target.dataset.alt;document.querySelectorAll('[data-photo]').forEach(b=>{b.classList.toggle('selected',b===target);b.setAttribute('aria-pressed',String(b===target))});const play=document.querySelector('.gallery-play');if(play)play.hidden=!target.classList.contains('selected')||target.dataset.photo!==courses.find(c=>location.hash.includes(c.id))?.cover;}
 if(target.dataset.section)document.getElementById(target.dataset.section)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
 if(target.dataset.contact){const c=courses.find(c=>c.id===target.dataset.contact);document.querySelector('#contact-course').textContent=`${c.title} · ${getInstitution(c.institution).name}`;document.querySelector('#contact-dialog').showModal()}
 if(target.dataset.social){const i=getInstitution(target.dataset.institute);document.querySelector('#social-title').textContent=socialNames[target.dataset.social];document.querySelector('#social-description').textContent=`${i.name} · Acceso a su comunidad y novedades.`;document.querySelector('#social-dialog').showModal()}
});

export function renderMarketplace(route,id){
 document.querySelector('#global-query').value=route==='buscar'?(params().q||''):'';
 if(route==='buscar')renderSearch();else if(route==='curso')renderCourse(id);else if(route==='instituciones')renderInstitutions();else if(route==='instituto')renderInstitute(id);
}
